    uint32_t len_q             = tiles_i * PROJ_SIZE * 2;
    uint32_t l1_addr_q_0       = (l1_tile_base);
    uint32_t l1_addr_q_1       = l1_addr_q_0 + (tiles_i_max * PROJ_SIZE * 2);
