    uint32_t l1_addr_o         = l1_addr_v_3 + (tiles_j_max * PROJ_SIZE * 2);
    uint32_t l2_addr_o         = (uint32_t)o_out + (tiles_i_max * ii * PROJ_SIZE * 2);
    uint32_t len_attn          = tiles_i * tiles_j * 2;
