            q_pt_next       = l1_addr_q_1;
            kt_pt           = l1_addr_kt_0;
            kt_pt_next      = l1_addr_kt_1;
            row_sum_pt      = l1_addr_row_sum_0;
            row_sum_pt_prev = l1_addr_row_sum_1;
