        case 0:
            attn_pt          = l1_addr_attn_0;
            attn_pt_prev     = l1_addr_attn_2;
            attn_pt_prev2    = l1_addr_attn_1;
            row_max_pt       = l1_addr_row_max_0;
            row_max_pt_prev  = l1_addr_row_max_2;
            row_max_pt_prev2 = l1_addr_row_max_1;
